"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/empty-state.css";
import { Package } from "@phosphor-icons/react";
import { useId, type ComponentPropsWithRef, type ReactNode } from "react";
import { cn } from "../../lib/cn";

export type EmptyStateProps = Omit<ComponentPropsWithRef<"div">, "title"> & {
  title: ReactNode;
  description?: ReactNode;
  icon?: ReactNode;
  primaryAction?: ReactNode;
  secondaryAction?: ReactNode;
  size?: "compact" | "default";
};

export function EmptyState({
  title,
  description,
  icon = <Package />,
  primaryAction,
  secondaryAction,
  size = "default",
  className,
  ...props
}: EmptyStateProps) {
  const generatedId = useId();
  const titleId = props["aria-labelledby"] ?? `${generatedId}-title`;
  const descriptionId = description ? `${generatedId}-description` : undefined;

  return (
    <div className={cn("whatiuse-empty-state", className)} data-size={size} aria-labelledby={titleId} aria-describedby={descriptionId} {...props}>
      <span className="whatiuse-empty-state__icon" aria-hidden="true">{icon}</span>
      <div className="whatiuse-empty-state__copy">
        <strong id={titleId}>{title}</strong>
        {description && <p id={descriptionId}>{description}</p>}
      </div>
      {(primaryAction || secondaryAction) && <div className="whatiuse-empty-state__actions">{primaryAction}{secondaryAction}</div>}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-empty-state {
  display: grid;
  width: min(460px, 100%);
  justify-items: center;
  gap: 14px;
  padding: 28px;
  color: var(--whatiuse-fg-default);
  text-align: center;
}

.whatiuse-empty-state[data-size="compact"] { gap: 10px; padding: 18px; }

.whatiuse-empty-state__icon { display: grid; width: 34px; height: 34px; place-items: center; border-radius: 50%; background: var(--whatiuse-bg-subtle); color: var(--whatiuse-fg-muted); }

.whatiuse-empty-state__icon svg { width: 17px; height: 17px; }

.whatiuse-empty-state__copy { display: grid; justify-items: center; gap: 5px; }

.whatiuse-empty-state__copy strong { font-size: 15px; font-weight: 590; letter-spacing: -0.018em; }

.whatiuse-empty-state__copy p { max-width: 42ch; margin: 0; color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-ui); line-height: 1.55; }

.whatiuse-empty-state__actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
}
